:where(small) {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-normal);
  line-height: 1.6667;
  color: var(--color-text-secondary);
}

:where(code, pre) {
  font-family: var(--font-family-code);
  font-size: var(--font-size-base);
  line-height: 1.4286;
}

